<script>
const content=document.getElementById('"'preview-content');
const dialog=document.getElementById('action-dialog');
let activeView='overview', checkedIn=42;
const classes=[{time:'4:00',period:'PM',name:'Intro to bouldering',coach:'With Alex · The cave',booked:8,total:10},{time:'5:30',period:'PM',name:'Finding your footwork',coach:'With Sam · Main wall',booked:6,total:8},{time:'6:00',period:'PM',name:'After-school climbers',coach:'With Jo · Training wall',booked:12,total:12}];
function classRows(){return classes.map(c=>"'`<div class="class-row"><div class="class-time">${c.time}<small>${c.period}</small></div><div class="class-name">${c.name}<small>${c.coach}</small></div><div class="capacity">${c.booked} / ${c.total}<div class="progress"><span style="width:${c.booked/c.total*100}%"></span></div></div></div>`).join('"'')}
function render(view){activeView=view;document.querySelectorAll('[data-view]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.view===view));b.tabIndex=b.dataset.view===view?0:-1});const names={overview:'Overview',memberships:'Memberships',classes:'Class bookings',passes:'Day passes'};document.getElementById('breadcrumb').textContent='Your gym / '+names[view];
if(view==='overview')content.innerHTML="'`<div class="app-title-row"><h2>A good day at the gym.</h2><button class="mini-btn" data-action="checkin">+ Check in</button></div><p class="app-subtitle">Here’s what’s happening today.</p><div class="stats"><div class="stat"><span class="stat-label">Checked in today</span><span class="stat-value">${checkedIn}</span><span class="stat-foot">A busy day on the wall</span></div><div class="stat"><span class="stat-label">Classes today</span><span class="stat-value">6</span><span class="stat-foot">3 still to come</span></div><div class="stat"><span class="stat-label">Day passes</span><span class="stat-value">18</span><span class="stat-foot">New faces, fresh chalk</span></div></div><div class="section-label"><h3>Coming up today</h3><span>Bookings / capacity</span></div>${classRows()}<div class="app-foot"><svg aria-hidden="true"><use href="#check"/></svg>Everything in its place. See you on the wall.</div>`;
if(view==='"'memberships')content.innerHTML="'`<div class="app-title-row"><h2>Your regulars.</h2><button class="mini-btn" data-action="checkin">+ Check in</button></div><p class="app-subtitle">Members, memberships, and familiar faces.</p><div class="stats"><div class="stat"><span class="stat-label">Active members</span><span class="stat-value">128</span></div><div class="stat"><span class="stat-label">Monthly</span><span class="stat-value">96</span></div><div class="stat"><span class="stat-label">Annual</span><span class="stat-value">32</span></div></div><div class="section-label"><h3>Member directory</h3><span>Sample members</span></div>${[['"'MC','Morgan Chen','Monthly membership','Active'],['AL','Avery Lewis','Annual membership','Active'],['RP','Riley Patel','Monthly membership','Active']].map(m=>"'`<div class="member-row"><span class="avatar">${m[0]}</span><div class="member-name">${m[1]}<small>${m[2]}</small></div><span class="status">${m[3]}</span></div>`).join('"'')}<p class=\"empty-caption\">A clear view of the people who make your gym.</p>"'`;
if(view==='"'classes')content.innerHTML="'`<div class="app-title-row"><h2>Room to learn.</h2><button class="mini-btn" data-action="booking">+ Book a class</button></div><p class="app-subtitle">Today’s classes and the people joining them.</p><div class="stats"><div class="stat"><span class="stat-label">Classes today</span><span class="stat-value">6</span></div><div class="stat"><span class="stat-label">Upcoming bookings</span><span class="stat-value">${classes.reduce((s,c)=>s+c.booked,0)}</span></div><div class="stat"><span class="stat-label">Spaces available</span><span class="stat-value">${classes.reduce((s,c)=>s+c.total-c.booked,0)}</span></div></div><div class="section-label"><h3>Upcoming classes</h3><span>Bookings / capacity</span></div>${classRows()}<p class="empty-caption">Try booking a place in this sample schedule.</p>`;
if(view==='"'passes')content.innerHTML="'`<div class="app-title-row"><h2>Welcome to the wall.</h2></div><p class="app-subtitle">A day of climbing starts here.</p><div class="pass-option"><div>Adult day pass<small>One climber · One visit</small></div><button class="mini-btn" data-action="pass" data-pass="Adult">Issue pass</button></div><div class="pass-option"><div>Youth day pass<small>One young climber · One visit</small></div><button class="mini-btn" data-action="pass" data-pass="Youth">Issue pass</button></div><div class="section-label" style="margin-top:23px"><h3>Recent day passes</h3><span>Today</span></div><div class="member-row"><span class="avatar">JD</span><div class="member-name">Jordan Davis<small>Adult day pass</small></div><span class="status">Checked in</span></div><div class="member-row"><span class="avatar">TK</span><div class="member-name">Taylor Kim<small>Youth day pass</small></div><span class="status">Checked in</span></div><p class="empty-caption">Demo only. No payments are processed.</p>`;
}
render('"'overview');
function explore(view){render(view);document.getElementById('demo').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});const app=document.getElementById('app-preview');app.classList.remove('demo-flash');void app.offsetWidth;app.classList.add('demo-flash');content.focus({preventScroll:true});}
document.querySelectorAll('[data-explore]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();explore(el.dataset.explore)}));
document.querySelectorAll('[data-view]').forEach(el=>{el.addEventListener('click',()=>render(el.dataset.view));el.addEventListener('keydown',e=>{if("'!['"'ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...el.parentElement.querySelectorAll('[data-view]')];let i=tabs.indexOf(el);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+tabs.length)%tabs.length;render(tabs[i].dataset.view);tabs[i].focus()})});
let dialogTrigger=null;
function openDialog(html,trigger){dialogTrigger=trigger||document.activeElement;document.getElementById('dialog-content').innerHTML=html;dialog.showModal()}
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{if(dialogTrigger?.isConnected)dialogTrigger.focus({preventScroll:true})});
content.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if("'!b)return;let type=b.dataset.action;if(type==='"'booking'){openDialog("'`<h2 id="dialog-title">Book a little progress.</h2><p>Choose a class from our sample schedule.</p>${classes.map((c,i)=>`<div class="pass-option"><div>${c.name}<small>${c.time} ${c.period} · ${c.total-c.booked} spaces left</small></div><button class="mini-btn" data-book="${i}" ${c.booked>=c.total?'"'disabled style=\"opacity:.5\"':''}>"'${c.booked>=c.total?'"'Full':'Book place'}</button></div>"'`).join('"'')}<p class=\"dialog-note\">Interactive demo · No real booking is made.</p>"'`,b);return}const passType=b.dataset.pass;openDialog(`<h2 id="dialog-title">${type==='"'checkin'?'A familiar face.':passType+' day pass.'}</h2><p>"'${type==='"'checkin'?'Try a member check-in in the demo.':'Issue a sample pass for your next visitor.'}</p><form id=\"demo-form\"><label for=\"climber-name\">Climber’s name</label><input id=\"climber-name\" name=\"name\" autocomplete=\"name\" placeholder=\"e.g. Morgan Chen\" required maxlength=\"80\"><button class=\"btn\" type=\"submit\">"'${type==='"'checkin'?'Check in climber':'Issue sample pass'} <svg aria-hidden=\"true\"><use href=\"#arrow\"/></svg></button></form><p class=\"dialog-note\">Demo only. No personal information is saved.</p>"'`,b);document.getElementById('"'demo-form').addEventListener('submit',ev=>{ev.preventDefault();const input=document.getElementById('climber-name');const name=input.value.trim();if("'!name){input.setCustomValidity('"'Enter a climber’s name.');input.reportValidity();return}checkedIn++;render(activeView);const message=document.createElement('p');message.className='result-message';message.setAttribute('role','status');message.textContent=type==='checkin'?"'`${name} is checked in. Their next climb awaits.`:`Sample ${passType.toLowerCase()} day pass issued for ${name}.`;document.getElementById('"'demo-form').replaceWith(message);dialogTrigger=content;});document.getElementById('climber-name').addEventListener('input',e=>e.target.setCustomValidity(''))});
dialog.addEventListener('click',e=>{const b=e.target.closest('[data-book]');if("'!b)return;const c=classes[Number(b.dataset.book)];if(c.booked>=c.total)return;c.booked++;render('"'classes');dialogTrigger=content;openDialog("'`<h2 id="dialog-title">You’re on the list.</h2><p class="result-message" role="status">A sample place is booked for ${c.name} at ${c.time} ${c.period}.</p><p class="dialog-note">Demo only. No real booking has been made.</p>`,content)});
let tourStep=0;const tour=[{title:'"'Meet your front desk.',text:'Your day at a glance: check-ins, class bookings, and day passes. Try the Check in button in the preview.',view:'overview'},{title:'Keep your community close.',text:'Open Memberships to see your regulars and their membership status together.',view:'memberships'},{title:'Make space for the next climb.',text:'Explore Class bookings to book a sample place, or Day passes to try issuing a visitor pass.',view:'classes'}];
function showTour(){const s=tour[tourStep];render(s.view);openDialog("'`<p class="eyebrow" style="margin-top:12px">A QUICK LOOK · ${tourStep+1} OF 3</p><h2 id="dialog-title">${s.title}</h2><p>${s.text}</p><button class="btn" id="next-tour">${tourStep===2?'"'Try it yourself':'Next'} <svg aria-hidden=\"true\"><use href=\"#arrow\"/></svg></button>"'`,document.getElementById('"'tour-button'));document.getElementById('next-tour').addEventListener('click',()=>{if(tourStep<2){tourStep++;showTour()}else{dialog.close();explore('classes')}})}
document.getElementById('tour-button').addEventListener('click',()=>{tourStep=0;showTour()});
const navToggle=document.querySelector('.nav-toggle'),nav=document.getElementById('navigation');navToggle.addEventListener('click',()=>{const open=navToggle.getAttribute('aria-expanded')==='true';navToggle.setAttribute('aria-expanded',String("'!open));navToggle.setAttribute('"'aria-label',open?'Open navigation':'Close navigation');nav.classList.toggle('open',"'!open)});nav.addEventListener('"'click',e=>{if(e.target.closest('a')){nav.classList.remove('open');navToggle.setAttribute('aria-expanded','false');navToggle.setAttribute('aria-label','Open navigation')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){nav.classList.remove('open');navToggle.setAttribute('aria-expanded','false');navToggle.focus()}});document.getElementById('year').textContent=new Date().getFullYear();
</script>
</body>
</html>
EOF"

